/**
 * Tool Comment Editor
 *
 * Inline comment editor shown at the top of the tool config panel.
 * Supports auto-generated comments, custom overrides, and reset/clear.
 */

import { useState, useEffect, useRef } from "react";
import { RotateCcw, X } from "lucide-react";
import type { Tool } from "@domain/workflow/entities/workflow";
import { generateComment } from "@domain/workflow/services/commentGenerator";

interface ToolCommentEditorProps {
  tool: Tool;
  onCommentChange: (toolId: string, comment: string | undefined) => void;
}

export default function ToolCommentEditor({
  tool,
  onCommentChange,
}: ToolCommentEditorProps) {
  const autoComment = generateComment(tool.type, tool.config);
  const isAutoGenerated = tool.comment === undefined;
  const isCleared = tool.comment === "";
  const displayValue = isAutoGenerated ? autoComment : tool.comment ?? "";

  const [editing, setEditing] = useState(false);
  const [draft, setDraft] = useState(displayValue);
  const textareaRef = useRef<HTMLTextAreaElement>(null);

  // Sync draft when tool changes
  useEffect(() => {
    if (!editing) {
      setDraft(isAutoGenerated ? autoComment : tool.comment ?? "");
    }
  }, [tool.id, tool.comment, autoComment, isAutoGenerated, editing]);

  // Focus textarea when entering edit mode
  useEffect(() => {
    if (editing && textareaRef.current) {
      textareaRef.current.focus();
      textareaRef.current.select();
    }
  }, [editing]);

  const handleSave = () => {
    setEditing(false);
    const trimmed = draft.trim();

    // If the text matches auto-generated, treat as "reset to auto"
    if (trimmed === autoComment || (trimmed === "" && !autoComment)) {
      if (!isAutoGenerated) {
        onCommentChange(tool.id, undefined);
      }
      return;
    }

    // Save whatever the user typed (including empty string to clear)
    onCommentChange(tool.id, trimmed);
  };

  const handleReset = () => {
    // Reset to auto-generated
    onCommentChange(tool.id, undefined);
    setDraft(autoComment);
    setEditing(false);
  };

  const handleClear = () => {
    // Explicit clear - no comment
    onCommentChange(tool.id, "");
    setDraft("");
    setEditing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === "Escape") {
      setDraft(isAutoGenerated ? autoComment : tool.comment ?? "");
      setEditing(false);
    }
    // Allow Shift+Enter for multiline, Enter alone saves
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSave();
    }
  };

  return (
    <div className="px-4 py-2 border-b border-theme-border-primary bg-theme-surface-panel">
      <div className="flex items-center justify-between mb-1">
        <label className="text-[10px] font-medium text-theme-text-tertiary uppercase tracking-wide">
          Comment
        </label>
        <div className="flex items-center gap-1">
          {/* Reset to auto-generated */}
          <button
            onClick={handleReset}
            disabled={isAutoGenerated}
            className="p-0.5 rounded transition-colors text-theme-text-tertiary hover:text-theme-text-primary disabled:opacity-30 disabled:cursor-not-allowed"
            title="Reset to auto-generated comment"
          >
            <RotateCcw className="w-3 h-3" />
          </button>
          {/* Clear comment */}
          <button
            onClick={handleClear}
            disabled={isCleared}
            className="p-0.5 rounded transition-colors text-theme-text-tertiary hover:text-theme-text-primary disabled:opacity-30 disabled:cursor-not-allowed"
            title="Clear comment"
          >
            <X className="w-3 h-3" />
          </button>
        </div>
      </div>

      {editing ? (
        <textarea
          ref={textareaRef}
          value={draft}
          onChange={(e) => setDraft(e.target.value)}
          onBlur={handleSave}
          onKeyDown={handleKeyDown}
          rows={2}
          className="w-full px-2 py-1 text-xs border rounded resize-y focus:outline-none focus:ring-1 focus:ring-theme-border-focus bg-theme-bg-input border-theme-border-primary text-theme-text-primary"
          placeholder="Add a comment…"
        />
      ) : (
        <button
          onClick={() => setEditing(true)}
          className="w-full text-left px-2 py-1 text-xs rounded border border-transparent hover:border-theme-border-primary transition-colors min-h-[28px]"
        >
          {isCleared ? (
            <span className="text-theme-text-tertiary italic">No comment</span>
          ) : (
            <span
              className={
                isAutoGenerated
                  ? "text-theme-text-tertiary italic"
                  : "text-theme-text-primary"
              }
            >
              {displayValue || (
                <span className="text-theme-text-tertiary italic">
                  Add a comment…
                </span>
              )}
            </span>
          )}
        </button>
      )}
    </div>
  );
}
